const fs   = require('fs');
const path = require('path');
const base = '/Users/jneal/n8n_projects';

const dirs = fs.readdirSync(base).filter(d => {
  try {
    const full = path.join(base, d);
    if (!fs.statSync(full).isDirectory()) return false;
    // Phase 2 must have produced media_timeline.json
    const hasTimeline = fs.existsSync(path.join(full, 'scripts', 'media_timeline.json'));
    // Skip if Phase 3 already complete
    const alreadyDone = fs.existsSync(path.join(full, 'renders', 'render_complete.json'));
    return hasTimeline && !alreadyDone;
  } catch(e) { return false; }
}).sort();

if (dirs.length === 0)
  throw new Error('No Phase 3 ready projects. Run Phase 2 first to produce scripts/media_timeline.json.');

const rows = dirs.map((d, i) => ({
  caseNumber: i + 1,
  slug:       d,
  projectDir: path.join(base, d)
}));

return [{ json: { readyProjects: dirs, allRows: JSON.stringify(rows) } }];

const fs   = require('fs');
const path = require('path');
const selection = parseInt($json['CASE NUMBER'], 10);
const allRows   = JSON.parse($('Scan Projects').first().json.allRows);

if (!selection || selection < 1 || selection > allRows.length)
  throw new Error(`Invalid selection: ${selection}. Choose 1–${allRows.length}.`);

const row        = allRows[selection - 1];
const projectDir = row.projectDir;
const slug       = row.slug;

const timelinePath = path.join(projectDir, 'scripts', 'media_timeline.json');
const timeline     = JSON.parse(fs.readFileSync(timelinePath, 'utf-8'));
const topic        = timeline.episode_title || slug;

const renderDir = path.join(projectDir, 'renders');

return [{ json: {
  slug,
  projectDir,
  topic,
  timelinePath,
  renderDir,
  renderScript:       '/Users/jneal/n8n_projects/render.js',
  renderLogPath:      path.join(renderDir, 'render.log'),
  renderPidPath:      path.join(renderDir, 'render.pid'),
  renderCompletePath: path.join(renderDir, 'render_complete.json'),
  finalVideoPath:     path.join(renderDir, 'final_video.mp4'),
  thumbnailPath:      path.join(renderDir, 'thumbnail.jpg'),
  summaryPath:        path.join(renderDir, 'phase3_complete.json'),
} }];

const fs   = require('fs');
const vars = $input.first().json;

fs.mkdirSync(vars.renderDir, { recursive: true });

const imagesDir = vars.projectDir + '/images';
const videosDir = vars.projectDir + '/videos';
const musicDir  = vars.projectDir + '/music';
const sfxDir    = vars.projectDir + '/sfx';

const imageCount = fs.existsSync(imagesDir) ? fs.readdirSync(imagesDir).filter(f => /\.(png|jpg)$/i.test(f)).length : 0;
const videoCount = fs.existsSync(videosDir) ? fs.readdirSync(videosDir).filter(f => f.endsWith('.mp4')).length  : 0;
const musicCount = fs.existsSync(musicDir)  ? fs.readdirSync(musicDir).filter(f => f.endsWith('.mp3')).length  : 0;
const sfxCount   = fs.existsSync(sfxDir)    ? fs.readdirSync(sfxDir).filter(f => f.endsWith('.mp3')).length    : 0;
const hasVoiceover = fs.existsSync(vars.projectDir + '/audio/voiceover_final.mp3');

if (!hasVoiceover)
  throw new Error('voiceover_final.mp3 not found. Run Phase 1 first.');

const timeline    = JSON.parse(fs.readFileSync(vars.timelinePath, 'utf-8'));
const totalScenes  = timeline.scenes.length;
const imageScenes  = timeline.scenes.filter(s => s.visual_type === 'image').length;
const videoScenes  = timeline.scenes.filter(s => s.visual_type === 'video').length;
const pinnedScenes = timeline.scenes.filter(s => s.visual_type && s.visual_type.startsWith('pinned')).length;
const totalDuration = timeline.total_duration_seconds || 0;

console.log(`Asset inventory:\n  Images:    ${imageCount} / ${imageScenes} scenes\n  Videos:    ${videoCount} / ${videoScenes} scenes\n  Pinned:    ${pinnedScenes} (channel intro etc)\n  Music:     ${musicCount} cue files\n  SFX:       ${sfxCount} cue files\n  Voiceover: YES\n  Duration:  ${(totalDuration/60).toFixed(1)} min (${totalScenes} scenes)`);

return [{ json: { ...vars, imageCount, videoCount, musicCount, sfxCount, totalScenes, totalDuration } }];

const fs   = require('fs');
const vars = $('Load Project').first().json;
const sd   = $getWorkflowStaticData('global');

sd.renderCheckAttempts = (sd.renderCheckAttempts || 0) + 1;
const MAX_ATTEMPTS = 50;

const isComplete = fs.existsSync(vars.renderCompletePath);

let progress = '';
if (fs.existsSync(vars.renderLogPath)) {
  try {
    const logContent = fs.readFileSync(vars.renderLogPath, 'utf-8');
    const lines = logContent.trim().split('\n').filter(Boolean);
    progress = lines.slice(-2).join(' | ');
  } catch(e) {}
}

console.log(`Render check ${sd.renderCheckAttempts}/${MAX_ATTEMPTS}: complete=${isComplete}`);
if (progress) console.log(`Log: ${progress}`);

if (!isComplete && sd.renderCheckAttempts >= MAX_ATTEMPTS)
  throw new Error(`Render timeout (${MAX_ATTEMPTS} checks). Check log: ${vars.renderLogPath}`);

return [{ json: { ...vars, isComplete, renderAttempts: sd.renderCheckAttempts, progress } }];

const fs   = require('fs');
const vars = $('Load Project').first().json;
const sd   = $getWorkflowStaticData('global');

// Read render completion data
const complete = JSON.parse(fs.readFileSync(vars.renderCompletePath, 'utf-8'));

const summary = {
  project:        vars.slug,
  topic:          vars.topic,
  phase3Complete: true,
  completedAt:    new Date().toISOString(),
  render: {
    outputPath:      complete.output_path,
    durationSeconds: complete.duration_seconds,
    durationMin:     parseFloat((complete.duration_seconds / 60).toFixed(1)),
    scenesRendered:  complete.scenes_rendered,
    assetsFound:     complete.assets_found,
    assetsMissing:   complete.assets_missing,
    renderComplete:  complete.completed_at,
  },
  thumbnailPath:  vars.thumbnailPath,
};

fs.writeFileSync(vars.summaryPath, JSON.stringify(summary, null, 2));
sd.renderCheckAttempts = 0; // reset counter for next run

console.log('=== PHASE 3 COMPLETE ===');
console.log(`Video   : ${summary.render.outputPath}`);
console.log(`Duration: ${summary.render.durationMin} min`);
console.log(`Scenes  : ${summary.render.scenesRendered} (${summary.render.assetsMissing} fallback black)`);

return [{ json: summary }];
